7925	@@ -0,0 +1,179 @@
7926	+'use strict';
7927	+// Eval exhaustion toy. See PREREG.md for the frozen model and predictions.
7928	+const fs = require('fs');
7929	+const path = require('path');
7930	+
7931	+const SIGMA_B = 1.5;
7932	+const SIGMA_U = 1.0;
7933	+const SD_TOT = Math.sqrt(SIGMA_B * SIGMA_B + SIGMA_U * SIGMA_U);
7934	+const P0 = 0.26;
7935	+const K = 16;
7936	+const G = 100;
7937	+const S0 = 0.06;
7938	+const RHO = 0.95;
7939	+const SIN_PHI = 0.2;
7940	+const COS_PHI = Math.sqrt(1 - SIN_PHI * SIN_PHI);
7941	+const NS = [500, 1000, 4000, 16000];
7942	+const SEEDS = 20;
7943	+const GATE_Z = 3;
7944	+
7945	+function mulberry32(a) {
7946	+  return function () {
7947	+    a |= 0; a = (a + 0x6D2B79F5) | 0;
7948	+    let t = Math.imul(a ^ (a >>> 15), 1 | a);
7949	+    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
7950	+    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
7951	+  };
7952	+}
7953	+function makeNormal(rand) {
7954	+  let spare = null;
7955	+  return function () {
7956	+    if (spare !== null) { const s = spare; spare = null; return s; }
7957	+    let u, v, s;
7958	+    do { u = rand() * 2 - 1; v = rand() * 2 - 1; s = u * u + v * v; } while (s >= 1 || s === 0);
7959	+    const m = Math.sqrt(-2 * Math.log(s) / s);
7960	+    spare = v * m;
7961	+    return u * m;
7962	+  };
7963	+}
7964	+function erf(x) {
7965	+  const sign = x < 0 ? -1 : 1; x = Math.abs(x);
7966	+  const t = 1 / (1 + 0.3275911 * x);
7967	+  const y = 1 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * Math.exp(-x * x);
7968	+  return sign * y;
7969	+}
7970	+const Phi = (x) => 0.5 * (1 + erf(x / Math.SQRT2));
7971	+function PhiInv(p) { // bisection, adequate here
7972	+  let lo = -8, hi = 8;
7973	+  for (let i = 0; i < 80; i++) { const mid = (lo + hi) / 2; if (Phi(mid) < p) lo = mid; else hi = mid; }
7974	+  return (lo + hi) / 2;
7975	+}
7976	+const A0 = PhiInv(P0) * SD_TOT;
7977	+const popAcc = (a) => Phi(a / SD_TOT);
7978	+
7979	+function runReuse(n, seed, gated) {
7980	+  const norm = makeNormal(mulberry32(seed));
7981	+  const b = new Float64Array(n);
7982	+  let u = new Float64Array(n);
7983	+  for (let i = 0; i < n; i++) { b[i] = SIGMA_B * norm(); u[i] = SIGMA_U * norm(); }
7984	+  let a = A0;
7985	+  let score = 0;
7986	+  for (let i = 0; i < n; i++) if (a - b[i] + u[i] > 0) score++;
7987	+  const rep = new Float64Array(G + 1), tru = new Float64Array(G + 1);
7988	+  rep[0] = score / n; tru[0] = popAcc(a);
7989	+  let cand = new Float64Array(n), best = new Float64Array(n);
7990	+  let accepted = 0;
7991	+  for (let g = 1; g <= G; g++) {
7992	+    const sg = S0 * Math.pow(RHO, g - 1);
7993	+    let bestScore = -1, bestDa = 0;
7994	+    for (let k = 0; k < K; k++) {
7995	+      const da = sg * norm();
7996	+      let sc = 0;
7997	+      const aa = a + da;
7998	+      for (let i = 0; i < n; i++) {
7999	+        const ui = COS_PHI * u[i] + SIN_PHI * SIGMA_U * norm();
8000	+        cand[i] = ui;
8001	+        if (aa - b[i] + ui > 0) sc++;
8002	+      }
8003	+      if (sc > bestScore) { bestScore = sc; bestDa = da; const t = best; best = cand; cand = t; }
8004	+    }
8005	+    const p = score / n;
8006	+    const thr = gated ? GATE_Z * Math.sqrt(p * (1 - p) / n) * n : 0;
8007	+    if (bestScore > score + thr) {
8008	+      a += bestDa; const t = u; u = best; best = t; score = bestScore; accepted++;
8009	+    }
8010	+    rep[g] = score / n; tru[g] = popAcc(a);
8011	+  }
8012	+  return { rep, tru, accepted };
8013	+}
8014	+
8015	+function runFresh(n, seed) {
8016	+  const norm = makeNormal(mulberry32(seed));
8017	+  let a = A0;
8018	+  const rep = new Float64Array(G + 1), tru = new Float64Array(G + 1);
8019	+  tru[0] = popAcc(a);
8020	+  rep[0] = tru[0] + Math.sqrt(tru[0] * (1 - tru[0]) / n) * norm();
8021	+  const b = new Float64Array(n), u = new Float64Array(n);
8022	+  let accepted = 0;
8023	+  for (let g = 1; g <= G; g++) {
8024	+    const sg = S0 * Math.pow(RHO, g - 1);
8025	+    let inc = 0;
8026	+    for (let i = 0; i < n; i++) { b[i] = SIGMA_B * norm(); u[i] = SIGMA_U * norm(); if (a - b[i] + u[i] > 0) inc++; }
8027	+    let bestScore = -1, bestDa = 0;
8028	+    for (let k = 0; k < K; k++) {
8029	+      const da = sg * norm();
8030	+      const aa = a + da;
8031	+      let sc = 0;
8032	+      for (let i = 0; i < n; i++) {
8033	+        const ui = COS_PHI * u[i] + SIN_PHI * SIGMA_U * norm();
8034	+        if (aa - b[i] + ui > 0) sc++;
8035	+      }
8036	+      if (sc > bestScore) { bestScore = sc; bestDa = da; }
8037	+    }
8038	+    if (bestScore > inc) { a += bestDa; accepted++; }
8039	+    tru[g] = popAcc(a);
8040	+    // reported on a second fresh block: unbiased binomial draw, normal approximation
8041	+    rep[g] = tru[g] + Math.sqrt(tru[g] * (1 - tru[g]) / n) * norm();
8042	+  }
8043	+  return { rep, tru, accepted };
8044	+}
8045	+
8046	+function meanCurves(runs) {
8047	+  const rep = new Array(G + 1).fill(0), tru = new Array(G + 1).fill(0);
8048	+  let acc = 0;
8049	+  for (const r of runs) { for (let g = 0; g <= G; g++) { rep[g] += r.rep[g]; tru[g] += r.tru[g]; } acc += r.accepted; }
8050	+  const m = runs.length;
8051	+  const gapFinal = runs.map((r) => r.rep[G] - r.tru[G]);
8052	+  const gm = gapFinal.reduce((x, y) => x + y, 0) / m;
8053	+  const gsd = Math.sqrt(gapFinal.reduce((x, y) => x + (y - gm) * (y - gm), 0) / (m - 1));
8054	+  return { rep: rep.map((x) => x / m), tru: tru.map((x) => x / m), accepted: acc / m, gapFinalMean: gm, gapFinalSE: gsd / Math.sqrt(m) };
8055	+}
8056	+
8057	+const t0 = Date.now();
8058	+const out = { params: { SIGMA_B, SIGMA_U, P0, K, G, S0, RHO, SIN_PHI, NS, SEEDS, GATE_Z }, cells: {} };
8059	+for (const n of NS) {
8060	+  const fresh = [], naive = [], gated = [];
8061	+  for (let s = 0; s < SEEDS; s++) {
8062	+    fresh.push(runFresh(n, 1000 + s));
8063	+    naive.push(runReuse(n, 2000 + s, false));
8064	+    gated.push(runReuse(n, 2000 + s, true));
8065	+  }
8066	+  out.cells[n] = { FRESH: meanCurves(fresh), NAIVE: meanCurves(naive), GATED: meanCurves(gated) };
8067	+  console.error(`n=${n} done at ${((Date.now() - t0) / 1000).toFixed(1)}s`);
8068	+}
8069	+
8070	+// ---- summary and prediction checks ----
8071	+const r3 = (x) => Math.round(x * 1000) / 1000;
8072	+const rows = [];
8073	+for (const n of NS) for (const arm of ['FRESH', 'NAIVE', 'GATED']) {
8074	+  const c = out.cells[n][arm];
8075	+  const repLate = c.rep[100] - c.rep[50], truLate = c.tru[100] - c.tru[50];
8076	+  const repEarly = c.rep[50] - c.rep[0], truEarly = c.tru[50] - c.tru[0];
8077	+  rows.push({
8078	+    n, arm,
8079	+    reported100: r3(c.rep[100]), true100: r3(c.tru[100]),
8080	+    gap100: r3(c.gapFinalMean), gapSE: r3(c.gapFinalSE),
8081	+    accepted: r3(c.accepted),
8082	+    phantomShareLate: repLate > 0 ? r3(1 - truLate / repLate) : null,
8083	+    lateEarlyReported: r3(repLate / repEarly), lateEarlyTrue: r3(truLate / truEarly),
8084	+  });
8085	+}
8086	+const cell = (n, arm) => rows.find((r) => r.n === n && r.arm === arm);
8087	+// P2 slope
8088	+const xs = NS.map((n) => Math.log(n)), ys = NS.map((n) => Math.log(out.cells[n].NAIVE.gapFinalMean));
8089	+const mx = xs.reduce((a, b) => a + b) / xs.length, my = ys.reduce((a, b) => a + b) / ys.length;
8090	+const slope = xs.reduce((a, x, i) => a + (x - mx) * (ys[i] - my), 0) / xs.reduce((a, x) => a + (x - mx) * (x - mx), 0);
8091	+const n4 = { F: cell(4000, 'FRESH'), N: cell(4000, 'NAIVE'), Gt: cell(4000, 'GATED') };
8092	+const checks = {
8093	+  P1: { value: n4.N.gap100, range: [0.08, 0.25], pass: n4.N.gap100 >= 0.08 && n4.N.gap100 <= 0.25 },
8094	+  P2: { slope: r3(slope), range: [-0.6, -0.4], pass: slope >= -0.6 && slope <= -0.4 },
8095	+  P3: { values: [500, 1000, 4000].map((n) => cell(n, 'NAIVE').phantomShareLate), pass: [500, 1000, 4000].every((n) => cell(n, 'NAIVE').phantomShareLate > 0.5) },
8096	+  P4a: { gated: n4.Gt.gap100, naive: n4.N.gap100, pass: n4.Gt.gap100 <= 0.5 * n4.N.gap100 },
8097	+  P4b: { fresh: n4.F.true100, naive: n4.N.true100, gated: n4.Gt.true100, pass: n4.F.true100 > n4.N.true100 && n4.N.true100 > n4.Gt.true100 },
8098	+  P5: { reported: n4.N.lateEarlyReported, true: n4.N.lateEarlyTrue, pass: n4.N.lateEarlyReported >= 2 * n4.N.lateEarlyTrue },
8099	+};
8100	+out.summary = rows; out.checks = checks;
8101	+fs.writeFileSync(path.join(__dirname, 'results.json'), JSON.stringify(out, null, 1));
8102	+console.table(rows);
8103	+console.log(JSON.stringify(checks, null, 1));
8104	+console.error(`total ${((Date.now() - t0) / 1000).toFixed(1)}s`);
