8108	--- /dev/null
8109	+++ b/output/eval_reuse_toys/sim2.js
8110	@@ -0,0 +1,224 @@
8111	+'use strict';
8112	+// Eval exhaustion, run 2: item-level feedback with a real learner. See PREREG_2.md.
8113	+const fs = require('fs');
8114	+const path = require('path');
8115	+
8116	+const D = 6, EPS = 0.10, N0 = 100, M = 10, G = 100, KC = 16, T = 5000;
8117	+const NS = [250, 1000, 4000, 16000];
8118	+const SEEDS = 10;
8119	+const ARMS = ['CLEAN', 'SCORE', 'LEAK', 'MIXED'];
8120	+
8121	+function mulberry32(a) {
8122	+  return function () {
8123	+    a |= 0; a = (a + 0x6D2B79F5) | 0;
8124	+    let t = Math.imul(a ^ (a >>> 15), 1 | a);
8125	+    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
8126	+    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
8127	+  };
8128	+}
8129	+function makeNormal(rand) {
8130	+  let spare = null;
8131	+  return function () {
8132	+    if (spare !== null) { const s = spare; spare = null; return s; }
8133	+    let u, v, s;
8134	+    do { u = rand() * 2 - 1; v = rand() * 2 - 1; s = u * u + v * v; } while (s >= 1 || s === 0);
8135	+    const m = Math.sqrt(-2 * Math.log(s) / s);
8136	+    spare = v * m;
8137	+    return u * m;
8138	+  };
8139	+}
8140	+function gen(rand, norm, count) {
8141	+  const X = new Float64Array(count * D), Y = new Int8Array(count);
8142	+  for (let i = 0; i < count; i++) {
8143	+    const o = i * D;
8144	+    for (let j = 0; j < D; j++) X[o + j] = norm();
8145	+    const clean = (X[o] + 0.7 * X[o + 1] * X[o + 2] - 0.3) > 0 ? 1 : -1;
8146	+    Y[i] = rand() < EPS ? -clean : clean;
8147	+  }
8148	+  return { X, Y, count };
8149	+}
8150	+function makeEval(set) {
8151	+  const nd = new Float64Array(set.count * 3).fill(Infinity);
8152	+  const nl = new Int8Array(set.count * 3);
8153	+  return { X: set.X, Y: set.Y, count: set.count, nd, nl };
8154	+}
8155	+function addPoints(E, bx, by, bcount) {
8156	+  const { X, nd, nl, count } = E;
8157	+  for (let i = 0; i < count; i++) {
8158	+    const o = i * D, b3 = i * 3;
8159	+    for (let b = 0; b < bcount; b++) {
8160	+      const p = b * D;
8161	+      let d2 = 0;
8162	+      for (let j = 0; j < D; j++) { const df = X[o + j] - bx[p + j]; d2 += df * df; }
8163	+      if (d2 < nd[b3 + 2]) {
8164	+        if (d2 < nd[b3 + 1]) {
8165	+          nd[b3 + 2] = nd[b3 + 1]; nl[b3 + 2] = nl[b3 + 1];
8166	+          if (d2 < nd[b3]) { nd[b3 + 1] = nd[b3]; nl[b3 + 1] = nl[b3]; nd[b3] = d2; nl[b3] = by[b]; }
8167	+          else { nd[b3 + 1] = d2; nl[b3 + 1] = by[b]; }
8168	+        } else { nd[b3 + 2] = d2; nl[b3 + 2] = by[b]; }
8169	+      }
8170	+    }
8171	+  }
8172	+}
8173	+function tentativeScore(E, bx, by, bcount) {
8174	+  const { X, Y, nd, nl, count } = E;
8175	+  let correct = 0;
8176	+  for (let i = 0; i < count; i++) {
8177	+    const o = i * D, b3 = i * 3;
8178	+    let d0 = nd[b3], d1 = nd[b3 + 1], dd2 = nd[b3 + 2];
8179	+    let l0 = nl[b3], l1 = nl[b3 + 1], l2 = nl[b3 + 2];
8180	+    for (let b = 0; b < bcount; b++) {
8181	+      const p = b * D;
8182	+      let d2 = 0;
8183	+      for (let j = 0; j < D; j++) { const df = X[o + j] - bx[p + j]; d2 += df * df; }
8184	+      if (d2 < dd2) {
8185	+        if (d2 < d1) {
8186	+          dd2 = d1; l2 = l1;
8187	+          if (d2 < d0) { d1 = d0; l1 = l0; d0 = d2; l0 = by[b]; }
8188	+          else { d1 = d2; l1 = by[b]; }
8189	+        } else { dd2 = d2; l2 = by[b]; }
8190	+      }
8191	+    }
8192	+    if ((l0 + l1 + l2 > 0 ? 1 : -1) === Y[i]) correct++;
8193	+  }
8194	+  return correct;
8195	+}
8196	+function accuracy(E) {
8197	+  let c = 0;
8198	+  for (let i = 0; i < E.count; i++) { const b3 = i * 3; if ((E.nl[b3] + E.nl[b3 + 1] + E.nl[b3 + 2] > 0 ? 1 : -1) === E.Y[i]) c++; }
8199	+  return c / E.count;
8200	+}
8201	+function failed(E) {
8202	+  const out = [];
8203	+  for (let i = 0; i < E.count; i++) { const b3 = i * 3; if ((E.nl[b3] + E.nl[b3 + 1] + E.nl[b3 + 2] > 0 ? 1 : -1) !== E.Y[i]) out.push(i); }
8204	+  return out;
8205	+}
8206	+function pickFailed(S, rand, want, bx, by, at) {
8207	+  const f = failed(S);
8208	+  const take = Math.min(want, f.length);
8209	+  for (let t = 0; t < take; t++) {
8210	+    const j = t + Math.floor(rand() * (f.length - t));
8211	+    const tmp = f[t]; f[t] = f[j]; f[j] = tmp;
8212	+    const src = f[t] * D, dst = (at + t) * D;
8213	+    for (let q = 0; q < D; q++) bx[dst + q] = S.X[src + q];
8214	+    by[at + t] = S.Y[f[t]];
8215	+  }
8216	+  return take;
8217	+}
8218	+function fillFresh(rand, norm, bx, by, from, to) {
8219	+  if (to <= from) return;
8220	+  const g = gen(rand, norm, to - from);
8221	+  bx.set(g.X, from * D);
8222	+  by.set(g.Y, from);
8223	+}
8224	+
8225	+function run(n, seed, arm) {
8226	+  const dRand = mulberry32(seed * 7919 + 17), dNorm = makeNormal(dRand);
8227	+  const train0 = gen(dRand, dNorm, N0);
8228	+  const S = makeEval(gen(dRand, dNorm, n));
8229	+  const Tt = makeEval(gen(dRand, dNorm, T));
8230	+  addPoints(S, train0.X, train0.Y, N0);
8231	+  addPoints(Tt, train0.X, train0.Y, N0);
8232	+  const aRand = mulberry32(seed * 104729 + ARMS.indexOf(arm) * 31 + n), aNorm = makeNormal(aRand);
8233	+  const rep = new Float64Array(G + 1), tru = new Float64Array(G + 1);
8234	+  rep[0] = accuracy(S); tru[0] = accuracy(Tt);
8235	+  let patches = 0, noisyPatches = 0;
8236	+  for (let g = 1; g <= G; g++) {
8237	+    let bx = new Float64Array(M * D), by = new Int8Array(M);
8238	+    if (arm === 'CLEAN') {
8239	+      fillFresh(aRand, aNorm, bx, by, 0, M);
8240	+    } else if (arm === 'SCORE') {
8241	+      let best = -1, bbx = null, bby = null;
8242	+      for (let k = 0; k < KC; k++) {
8243	+        const c = gen(aRand, aNorm, M);
8244	+        const sc = tentativeScore(S, c.X, c.Y, M);
8245	+        if (sc > best) { best = sc; bbx = c.X; bby = c.Y; }
8246	+      }
8247	+      bx = bbx; by = bby;
8248	+    } else {
8249	+      const want = arm === 'LEAK' ? M : M / 2;
8250	+      const took = pickFailed(S, aRand, want, bx, by, 0);
8251	+      patches += took;
8252	+      for (let t = 0; t < took; t++) {
8253	+        const o = t * D;
8254	+        const clean = (bx[o] + 0.7 * bx[o + 1] * bx[o + 2] - 0.3) > 0 ? 1 : -1;
8255	+        if (by[t] !== clean) noisyPatches++;
8256	+      }
