"""Locate differences between two toy-run result JSON files."""
import json
import sys

a_bytes, b_bytes = open(sys.argv[1], "rb").read(), open(sys.argv[2], "rb").read()
print("sizes:", len(a_bytes), len(b_bytes), "crlf in a/b:", b"\r\n" in a_bytes, b"\r\n" in b_bytes)
a, b = json.loads(a_bytes), json.loads(b_bytes)

diffs = []


def walk(x, y, path):
    if type(x) is not type(y):
        diffs.append((path, x, y))
    elif isinstance(x, dict):
        for k in sorted(set(x) | set(y)):
            if k not in x or k not in y:
                diffs.append((path + "/" + k, x.get(k), y.get(k)))
            else:
                walk(x[k], y[k], path + "/" + k)
    elif isinstance(x, list):
        if len(x) != len(y):
            diffs.append((path, f"len {len(x)}", f"len {len(y)}"))
        for i, (p, q) in enumerate(zip(x, y)):
            walk(p, q, f"{path}[{i}]")
    elif x != y:
        diffs.append((path, x, y))


walk(a, b, "")
print("differing leaves:", len(diffs))
maxrel = 0.0
for path, x, y in diffs:
    if isinstance(x, float) and isinstance(y, float) and x:
        maxrel = max(maxrel, abs(x - y) / abs(x))
print("max relative difference:", maxrel)
for d in diffs[:15]:
    print(d)
print("checks equal:", a.get("checks") == b.get("checks"))
print("summary equal:", a.get("summary") == b.get("summary"))

