from fractions import Fraction as Q
from functools import lru_cache


def greedy(hits, state):
    if hits == 0:
        return Q(0)
    chosen = max(state, key=lambda pair: (Q(pair[1], pair[0]), -pair[0]))
    return step(hits, state, chosen, greedy)


def step(hits, state, chosen, value):
    size, failures = chosen
    rest = list(state)
    rest.remove(chosen)
    p = Q(failures, size)
    after_hit = tuple(sorted(rest + ([(size - 1, failures - 1)] if failures > 1 else [])))
    result = 1 + p * value(hits - 1, after_hit)
    if p < 1:
        after_miss = tuple(sorted(rest + [(size - 1, failures)]))
        result += (1 - p) * value(hits, after_miss)
    return result


@lru_cache(maxsize=None)
def optimal(hits, state):
    if hits == 0:
        return Q(0)
    return min(step(hits, state, chosen, optimal) for chosen in set(state))


