"""Can any index rule be optimal for the adaptive patch schedule?

An index policy scores each category by a function of its own (size,
failures) and the hits still needed, then patches the max.  It is defeated by
a pairwise preference reversal: two categories A, B present in two states with
the same requirement, A strictly better first in one and B strictly better in
the other.  Also tests a few candidate rules against the optimum.
"""
import sys
from fractions import Fraction as Q
from functools import lru_cache
from itertools import combinations_with_replacement


def continuation(hits, state, chosen, value):
    size, failures = chosen
    rest = list(state)
    rest.remove(chosen)
    p = Q(failures, size)
    after_hit = tuple(sorted(rest + ([(size - 1, failures - 1)] if failures > 1 else [])))
    result = 1 + p * value(hits - 1, after_hit)
    if p < 1:
        after_miss = tuple(sorted(rest + [(size - 1, failures)]))
        result += (1 - p) * value(hits, after_miss)
    return result


@lru_cache(maxsize=None)
def optimal(hits, state):
    if hits == 0:
        return Q(0)
    return min(continuation(hits, state, c, optimal) for c in set(state))


MAX_SIZE = int(sys.argv[1]) if len(sys.argv) > 1 else 4
MAX_CATS = int(sys.argv[2]) if len(sys.argv) > 2 else 3
pairs = [(n, f) for n in range(1, MAX_SIZE + 1) for f in range(1, n + 1)]
states = []
for k in range(1, MAX_CATS + 1):
    for combo in combinations_with_replacement(pairs, k):
        state = tuple(sorted(combo))
        total = sum(f for _, f in state)
        for hits in range(1, total + 1):
            states.append((hits, state))
print("states:", len(states))

# pairwise preferences: (A, B, hits) -> set of signs observed across states containing both
prefs = {}
for hits, state in states:
    distinct = sorted(set(state))
    conts = {c: continuation(hits, state, c, optimal) for c in distinct}
    for i, a in enumerate(distinct):
        for b in distinct[i + 1:]:
            sign = (conts[a] > conts[b]) - (conts[a] < conts[b])
            prefs.setdefault((a, b, hits), {}).setdefault(sign, (hits, state, conts[a], conts[b]))
reversals = [(key, v) for key, v in prefs.items() if 1 in v and -1 in v]
print("pairs with strict preference both ways (no (n,F,H) index can be optimal):", len(reversals))
for key, v in reversals[:6]:
    print(" ", key, "A first better in", v[-1][1], "B first better in", v[1][1])

# also allow the index to depend on total failures and total items remaining
prefs2 = {}
for hits, state in states:
    distinct = sorted(set(state))
    conts = {c: continuation(hits, state, c, optimal) for c in distinct}
    tot = (sum(n for n, _ in state), sum(f for _, f in state))
    for i, a in enumerate(distinct):
        for b in distinct[i + 1:]:
            sign = (conts[a] > conts[b]) - (conts[a] < conts[b])
            prefs2.setdefault((a, b, hits, tot), {}).setdefault(sign, state)
rev2 = [(k, v) for k, v in prefs2.items() if 1 in v and -1 in v]
print("reversals even with (total items, total failures) in the index:", len(rev2))
for k, v in rev2[:4]:
    print(" ", k, v)

# candidate rules
def rule_rate_small(hits, state):
    return max(state, key=lambda c: (Q(c[1], c[0]), -c[0]))

def rule_rate_large(hits, state):
    return max(state, key=lambda c: (Q(c[1], c[0]), c[0]))

def rule_finisher(hits, state):
    # when one hit remains, best finisher (n+1)/(F+1) smallest == max rate anyway; otherwise max rate, ties to large
    return max(state, key=lambda c: (Q(c[1], c[0]), c[0]))

def rule_rate_then_keep_finisher(hits, state):
    # max rate; among ties prefer the category whose single-hit expectation is WORST (save the best finisher)
    return max(state, key=lambda c: (Q(c[1], c[0]), Q(c[0] + 1, c[1] + 1)))

def rule_lookahead(hits, state):
    # one-step lookahead with greedy-small continuation
    @lru_cache(maxsize=None)
    def greedy_value(h, s):
        if h == 0:
            return Q(0)
        return continuation(h, s, rule_rate_small(h, s), greedy_value)
    return min(set(state), key=lambda c: (continuation(hits, state, c, greedy_value), c))

for name, rule in [("rate, ties small", rule_rate_small), ("rate, ties large", rule_rate_large),
                   ("rate, ties save best finisher", rule_rate_then_keep_finisher),
                   ("one-step lookahead over greedy", rule_lookahead)]:
    bad = 0
    first = None
    for hits, state in states:
        chosen = rule(hits, state)
        if continuation(hits, state, chosen, optimal) != optimal(hits, state):
            bad += 1
            first = first or (hits, state, chosen)
    print(f"rule '{name}': suboptimal first choice in {bad} of {len(states)} states; first:", first)

