"""Structural facts about the optimal adaptive patch policy, by enumeration.

Questions:
 Q1 equal rates, H >= 2: is a largest category always an optimal first choice?
 Q2 for a fixed state, as H rises from 1 to total, does the optimal-first set change at most once (one switch)?
 Q3 is an optimal first choice always among {max rate} U {max size} U {best finisher} U {worst finisher}?
 Q4 does the optimal choice ever go to a category that is dominated (smaller rate AND smaller size) by another?
 Q5 commutation check: with >= 2 hits remaining, patching A then B vs B then A then same optimal continuation gives equal value.
 Q6 does an optimal policy ever patch a category with the minimum rate when there are >= 3 distinct rates?
"""
import sys
from fractions import Fraction as Q
from functools import lru_cache
from itertools import combinations_with_replacement


def continuation(hits, state, chosen, value):
    size, failures = chosen
    rest = list(state)
    rest.remove(chosen)
    p = Q(failures, size)
    after_hit = tuple(sorted(rest + ([(size - 1, failures - 1)] if failures > 1 else [])))
    result = 1 + p * value(hits - 1, after_hit)
    if p < 1:
        after_miss = tuple(sorted(rest + [(size - 1, failures)]))
        result += (1 - p) * value(hits, after_miss)
    return result


@lru_cache(maxsize=None)
def optimal(hits, state):
    if hits == 0:
        return Q(0)
    return min(continuation(hits, state, c, optimal) for c in set(state))


def two_step(hits, state, first, second):
    """Patch first then second (second may vanish after a hit on first if it was first's last failure; handle)."""
    size, failures = first
    rest = list(state)
    rest.remove(first)
    p = Q(failures, size)
    total = Q(0)
    for hit, prob in ((True, p), (False, 1 - p)):
        if prob == 0:
            continue
        h = hits - 1 if hit else hits
        new_first = (size - 1, failures - 1) if hit else (size - 1, failures)
        s = tuple(sorted(rest + ([new_first] if new_first[1] > 0 else [])))
        if h == 0:
            total += prob * 1
            continue
        if second in s:
            total += prob * (1 + continuation(h, s, second, optimal))
        else:
            total += prob * (1 + optimal(h, s))
    return total


MAX_SIZE = int(sys.argv[1]) if len(sys.argv) > 1 else 5
MAX_CATS = int(sys.argv[2]) if len(sys.argv) > 2 else 4
pairs = [(n, f) for n in range(1, MAX_SIZE + 1) for f in range(1, n + 1)]
states = []
for k in range(1, MAX_CATS + 1):
    for combo in combinations_with_replacement(pairs, k):
        states.append(tuple(sorted(combo)))
print("multiset states:", len(states))

rate = lambda c: Q(c[1], c[0])
finisher = lambda c: Q(c[0] + 1, c[1] + 1)

q1_bad = []; q2_bad = []; q3_bad = []; q4_bad = []; q5_bad = 0; q5_checked = 0; q6_bad = []
for state in states:
    total = sum(f for _, f in state)
    distinct = sorted(set(state))
    best_sets = []
    for hits in range(1, total + 1):
        vals = {c: continuation(hits, state, c, optimal) for c in distinct}
        best = min(vals.values())
        opt = {c for c, v in vals.items() if v == best}
        best_sets.append(opt)
        top_rate = max(rate(c) for c in distinct)
        # Q1
        if hits >= 2 and len({rate(c) for c in distinct}) == 1 and len(distinct) > 1:
            largest = max(c[0] for c in distinct)
            if not any(c[0] == largest for c in opt):
                q1_bad.append((hits, state, sorted(opt)))
        # Q3
        cand = {max(distinct, key=rate), max(distinct, key=lambda c: c[0]), min(distinct, key=finisher), max(distinct, key=finisher)}
        if not (opt & cand):
            q3_bad.append((hits, state, sorted(opt)))
        # Q4 dominated choice
        for c in opt:
            if any(d != c and rate(d) >= rate(c) and d[0] >= c[0] and (rate(d) > rate(c) or d[0] > c[0]) for d in distinct):
                if not any(d in opt for d in distinct if d != c and rate(d) >= rate(c) and d[0] >= c[0] and d != c):
                    q4_bad.append((hits, state, c, sorted(opt)))
                break
        # Q6 minimum rate chosen with >=3 distinct rates
        rates = sorted({rate(c) for c in distinct})
        if len(rates) >= 3 and all(rate(c) == rates[0] for c in opt):
            q6_bad.append((hits, state, sorted(opt)))
        # Q5 commutation
        if hits >= 2 and len(distinct) >= 2:
            for a in distinct:
                for b in distinct:
                    if a < b:
                        q5_checked += 1
                        if two_step(hits, state, a, b) != two_step(hits, state, b, a):
                            q5_bad += 1
    # Q2: number of changes of the optimal set along H
    changes = sum(1 for i in range(1, len(best_sets)) if best_sets[i] != best_sets[i - 1])
    if changes > 1:
        q2_bad.append((state, [sorted(s) for s in best_sets]))

print("Q1 equal rates & H>=2, largest not optimal:", len(q1_bad), q1_bad[:3])
print("Q2 states with more than one switch of the optimal set along H:", len(q2_bad))
for row in q2_bad[:4]:
    print("   ", row)
print("Q3 optimal choice outside {max rate, max size, best finisher, worst finisher}:", len(q3_bad), q3_bad[:3])
print("Q4 optimal choice dominated in rate and size by an unchosen category:", len(q4_bad), q4_bad[:3])
print("Q5 commutation (>=2 hits remain): violations", q5_bad, "of", q5_checked)
print("Q6 only the minimum of >=3 rates is optimal:", len(q6_bad), q6_bad[:3])

