            "state": ((5, 3), (8, 5), (9, 6)), "hits_needed": 3, "values": _render_values(lowest),
            "rates": _render_values(rates),
            "refuted": (lowest[(5, 3)] < lowest[(8, 5)] and lowest[(5, 3)] < lowest[(9, 6)]
