"""Two categories, refined: ignoring ties, does the unique optimal first choice ever switch back?

Label per H in 1..total-1: 'A', 'B' or tie.  Conjecture S': the subsequence of non-tie labels is A*B* or B*A*.
Also: C4 -- at H = 1 the better finisher (smaller (n+1)/(F+1)) is always optimal (ties allowed).
"""
import sys
from fractions import Fraction as Q
from functools import lru_cache


def continuation(hits, state, chosen, value):
    size, failures = chosen
    rest = list(state)
    rest.remove(chosen)
    p = Q(failures, size)
    after_hit = tuple(sorted(rest + ([(size - 1, failures - 1)] if failures > 1 else [])))
    result = 1 + p * value(hits - 1, after_hit)
    if p < 1:
        after_miss = tuple(sorted(rest + [(size - 1, failures)]))
        result += (1 - p) * value(hits, after_miss)
    return result


@lru_cache(maxsize=None)
def optimal(hits, state):
    if hits == 0:
        return Q(0)
    return min(continuation(hits, state, c, optimal) for c in set(state))


N = int(sys.argv[1]) if len(sys.argv) > 1 else 14
pairs = [(n, f) for n in range(1, N + 1) for f in range(1, n + 1)]
fin = lambda c: Q(c[0] + 1, c[1] + 1)
checked = 0
violations = []
c4_bad = []
c4_checked = 0
switches = {0: 0, 1: 0}
for i, a in enumerate(pairs):
    for b in pairs[i + 1:]:
        state = (a, b)
        total = a[1] + b[1]
        labels = []
        for hits in range(1, total):
            va = continuation(hits, state, a, optimal)
            vb = continuation(hits, state, b, optimal)
            labels.append("A" if va < vb else "B" if vb < va else None)
            if hits == 1 and fin(a) != fin(b):
                c4_checked += 1
                better_is_a = fin(a) < fin(b)
                if (va < vb and not better_is_a) or (vb < va and better_is_a):
                    c4_bad.append((state, va, vb))
        uniq = [l for l in labels if l]
        if total >= 3:
            checked += 1
            changes = sum(1 for x, y in zip(uniq, uniq[1:]) if x != y)
            if changes > 1:
                violations.append((state, labels))
            else:
                switches[changes] = switches.get(changes, 0) + 1
print(f"two-category states (total >= 3) checked: {checked}; switch-back violations: {len(violations)}; no switch: {switches.get(0)}, one switch: {switches.get(1)}")
for row in violations[:8]:
    print("   ", row)
print(f"C4 (H=1: better finisher optimal, ties allowed): checked {c4_checked}, violations {len(c4_bad)}")
for row in c4_bad[:5]:
    print("   ", row)
# direction of the single switch: from the better finisher to the worse one?
direction = {"better_to_worse": 0, "worse_to_better": 0}
for i, a in enumerate(pairs):
    for b in pairs[i + 1:]:
        state = (a, b)
        total = a[1] + b[1]
        if total < 3 or fin(a) == fin(b):
            continue
        uniq = []
        for hits in range(1, total):
            va = continuation(hits, state, a, optimal)
            vb = continuation(hits, state, b, optimal)
            if va != vb:
                uniq.append(a if va < vb else b)
        if len(set(uniq)) == 2:
            first = uniq[0]
            better = a if fin(a) < fin(b) else b
            direction["better_to_worse" if first == better else "worse_to_better"] += 1
print("single-switch direction:", direction)

