"""H = 1: is the optimal value exactly min_c (n_c+1)/(F_c+1), and is max-rate-first suboptimal somewhere?"""
import sys
from fractions import Fraction as Q
from functools import lru_cache
from itertools import combinations_with_replacement


def continuation(hits, state, chosen, value):
    size, failures = chosen
    rest = list(state)
    rest.remove(chosen)
    p = Q(failures, size)
    after_hit = tuple(sorted(rest + ([(size - 1, failures - 1)] if failures > 1 else [])))
    result = 1 + p * value(hits - 1, after_hit)
    if p < 1:
        after_miss = tuple(sorted(rest + [(size - 1, failures)]))
        result += (1 - p) * value(hits, after_miss)
    return result


@lru_cache(maxsize=None)
def optimal(hits, state):
    if hits == 0:
        return Q(0)
    return min(continuation(hits, state, c, optimal) for c in set(state))


fin = lambda c: Q(c[0] + 1, c[1] + 1)
state = ((2, 1), (16, 9))
vals = {c: continuation(1, state, c, optimal) for c in state}
print("witness", state, {c: str(v) for c, v in vals.items()}, "optimal", optimal(1, state), "min finisher", min(fin(c) for c in state))

N = int(sys.argv[1]) if len(sys.argv) > 1 else 8
K = int(sys.argv[2]) if len(sys.argv) > 2 else 4
pairs = [(n, f) for n in range(1, N + 1) for f in range(1, n + 1)]
bad = 0
checked = 0
greedy_bad = []
for k in range(1, K + 1):
    for combo in combinations_with_replacement(pairs, k):
        s = tuple(sorted(combo))
        checked += 1
        if optimal(1, s) != min(fin(c) for c in s):
            bad += 1
        vals = {c: continuation(1, s, c, optimal) for c in set(s)}
        greedy = max(set(s), key=lambda c: (Q(c[1], c[0]), -c[0]))
        if vals[greedy] != min(vals.values()):
            greedy_bad.append((s, greedy, str(vals[greedy]), str(min(vals.values()))))
print(f"H=1 value == min finisher on {checked - bad} of {checked} states (sizes<={N}, cats<={K})")
print(f"greedy (max rate, ties small) suboptimal at H=1 in {len(greedy_bad)} states; first:", greedy_bad[:3])

